STATIC_ABILITY.CONTINUOUS_ACTION:
if EffectSource() ~= nil then local characteristics = EffectSource():GetCurrentCharacteristics() local filter = ClearFilter()
filter:Add( FE_SUBTYPE, OP_IS, LAND_TYPE_SWAMP ) filter:Add( FE_CONTROLLER, OP_IS, EffectController()) local total = filter:Count()
characteristics:Power_Set( total ) characteristics:Toughness_Set( total ) end
